import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 16
#define SPLIT_K 32

// Split-K tiled matmul: C = A * B
// A: (M, K) row-major, B: (K, N) row-major, C: (M, N) row-major
// K is very large while M and N are small, so we partition K across
// gridDim.z blocks. Each block computes a partial sum over its K-chunk
// using shared-memory tiling and accumulates into C via atomicAdd.
__global__ void matmul_splitk_kernel(const float* __restrict__ A,
                                     const float* __restrict__ B,
                                     float* __restrict__ C,
                                     int M, int N, int K) {
    int chunk = (K + gridDim.z - 1) / gridDim.z;
    int k_start = blockIdx.z * chunk;
    int k_end = min(k_start + chunk, K);

    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;

    __shared__ float As[TILE][TILE + 1];
    __shared__ float Bs[TILE][TILE + 1];

    float acc = 0.0f;

    for (int t = k_start; t < k_end; t += TILE) {
        int a_col = t + threadIdx.x;
        int b_row = t + threadIdx.y;

        As[threadIdx.y][threadIdx.x] =
            (row < M && a_col < k_end) ? A[(long)row * K + a_col] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] =
            (b_row < k_end && col < N) ? B[(long)b_row * N + col] : 0.0f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        atomicAdd(&C[(long)row * N + col], acc);
    }
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE, SPLIT_K);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_splitk_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
'''

cpp_src = "torch::Tensor matmul(torch::Tensor A, torch::Tensor B);"

matmul_op = load_inline(
    name="matmul_splitk_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matmul"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication (C = A * B) optimized for a very large K dimension
    using a custom split-K CUDA kernel with shared-memory tiling and atomic
    accumulation of partial products.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        A = A.contiguous().float()
        B = B.contiguous().float()
        return matmul_op.matmul(A, B)

